import React from 'react';
import {createRoot} from 'react-dom/client';
import Workspace from '../../app/fire-inspections/workspace';
import {normalizeCode,type CodeEntry} from '../../app/fire-inspections/codes';
import {clearInspectionRecovery} from '../../app/fire-inspections/durable-store';
import {emptyTeam,reviewBasis,reviewTransition,ownerIdentityId} from '../../app/fire-inspections/team-workflow';
import {normalizeInspection,validateInspection,followUpRecord,emptyInspection,freshCheck,type InspectionRecord,type InspectionFile,type Property} from '../../app/fire-inspections/model';
import {normalizePropertyProfile,type PropertyProfile} from '../../app/fire-inspections/property-profiles';
import {defaultReminderDraftPolicy} from '../../app/fire-inspections/reminder-drafts';
if(!['127.0.0.1','localhost'].includes(location.hostname))throw Error('Local fixture only.');
let records:InspectionRecord[]=JSON.parse(localStorage.getItem('inspection-fixture')||'[]'),fail=false;
let codes:CodeEntry[]=JSON.parse(sessionStorage.getItem('inspection-code-fixture')||'[]');
let attachments:InspectionFile[]=JSON.parse(sessionStorage.getItem('inspection-file-fixture')||'[]');
const photoReceipts=new Map<string,{hash:string;attachment:InspectionFile}>(JSON.parse(sessionStorage.getItem('inspection-photo-receipts')||'[]'));
const profileMap=new Map<string,PropertyProfile>();
const properties:Property[]=[{id:'fictional-property',name:'Fictional practice property',address:'100 Test Way'}];
window.fetch=async(input,options)=>{
 if(!String(input).startsWith('/api/fire-inspections'))return Response.json({error:'Unexpected fixture request'},{status:400});
 if(!navigator.onLine)throw TypeError('The local fixture is offline. Exact draft and photo recovery remain on this device.');
 if(String(input).includes('/contact-cards'))return !options?.method||options.method==='GET'?Response.json({cards:[]}):Response.json({error:'Business card storage requires the real authenticated private API. This local layout fixture does not upload contact cards.'},{status:501});
 if(String(input).includes('/cases')){if(options?.method&&options.method!=='GET')return Response.json({error:'Case decisions require the real private API. This local layout fixture does not verify or issue a correction decision.'},{status:501});const reports=await Promise.all(records.filter(record=>record.kind==='inspection'&&record.data.status==='Completed').map(async record=>({inspectionId:record.id,inspectionVersion:record.version,payloadHash:Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(record.data)))),n=>n.toString(16).padStart(2,'0')).join(''),title:record.data.title,address:record.data.address,propertyId:record.data.propertyId,checkId:'',checkLabel:'',observation:''})));return Response.json({permissions:['records.read','corrections.write','corrections.review','reports.amend','reports.void'],userId:'qa-fixture-owner',role:'owner',cases:[],actions:[],files:[],reports,targets:reports.flatMap(source=>records.find(record=>record.id===source.inspectionId)!.data.checks.filter(check=>check.result==='Needs attention').map(check=>({...source,checkId:check.id,checkLabel:check.label,observation:check.observation,result:check.result})))});}
 if(String(input).includes('/staff'))return Response.json({access:{role:'owner',permissions:['staff.manage','staff.read'],rolloutEnabled:false},rolloutEnabled:false,members:[],identities:[],owner:{protected:true}});
 if(String(input).includes('/reminders'))return !options?.method||options.method==='GET'?Response.json({policy:defaultReminderDraftPolicy(),deliveryMode:'draft-only',dispatchHold:null,drafts:[],nextCursor:null,runs:[],skips:[],access:{permissions:['reminders.read','reminders.manage','automation.run']},schedule:{localTime:'07:00',timeZone:'America/Chicago',checkEveryMinutes:15,verified:false}}):Response.json({error:'Reminder generation requires the real authenticated private API. This local layout fixture does not create cloud drafts or verify a deployed schedule.'},{status:501});
 if(String(input).includes('/backups'))return !options?.method||options.method==='GET'?Response.json({jobs:[],dispatchHolds:[]}):Response.json({error:'Cloud backup operations require the real private API; this local visual fixture does not simulate a verified backup.'},{status:501});
 if(String(input).includes('/property-profile')&&options?.method==='POST'){const body=JSON.parse(String(options.body)),saved=profileMap.get(body.id);if(!properties.some(property=>property.id===body.id)||(saved?.version??0)!==body.version)return Response.json({error:'Property profile changed.'},{status:409});try{const profile={id:body.id,version:body.version+1,data:normalizePropertyProfile(body.data),updatedAt:new Date().toISOString(),updatedBy:'fictional@example.invalid'};profileMap.set(body.id,profile);return Response.json({saved:true,profile});}catch(problem){return Response.json({error:String(problem)},{status:400});}}
 if(String(input).includes('/files')&&options?.method==='POST'){
  const form=options.body as FormData,file=form.get('file') as File,recordId=String(form.get('recordId')??''),checkId=String(form.get('checkId')??''),caption=String(form.get('caption')??'').trim(),id=String(form.get('uploadId')??crypto.randomUUID());
  if(!file||typeof file.arrayBuffer!=='function')return Response.json({error:'Choose a local fixture photo.'},{status:400});
  const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),n=>n.toString(16).padStart(2,'0')).join(''),existing=photoReceipts.get(id),current=records.find(record=>record.id===recordId);
  if(existing){const attachment=existing.attachment;if(existing.hash!==hash||attachment.recordId!==recordId||(attachment.checkId??'')!==checkId||attachment.caption!==caption||attachment.filename!==file.name)return Response.json({error:'Upload identifier already belongs to different original bytes or metadata.'},{status:409});return Response.json({attachment,record:current,acceptedVersion:attachment.recordVersion,replayed:true});}
  if(!current||current.archived||['Completed','Canceled'].includes(current.data.status))return Response.json({error:'Confirm an open fixture inspection before uploading.'},{status:409});
  const frozen=current.data.evidenceManifest.find(entry=>entry.id===id&&entry.sha256===hash&&(entry.checkId??'')===checkId&&entry.filename===file.name&&entry.caption===caption&&entry.size===file.size&&entry.contentType===file.type);
  if(!frozen&&(current.data.inspectorAttested||current.data.representative.state==='Signed'||current.data.inspectorSignature.state==='Signed'))return Response.json({error:'A signed record accepts only its exact frozen manifest evidence.'},{status:409});
  const record=frozen?current:{...current,version:current.version+1,updatedAt:new Date().toISOString()};records=records.map(old=>old.id===record.id?record:old);localStorage.setItem('inspection-fixture',JSON.stringify(records));
  const attachment={id,recordId,checkId,caption,filename:file.name,size:file.size,contentType:file.type,recordVersion:record.version,createdAt:new Date().toISOString()};attachments=[attachment,...attachments.filter(old=>old.id!==id)];photoReceipts.set(id,{hash,attachment});sessionStorage.setItem('inspection-file-fixture',JSON.stringify(attachments));sessionStorage.setItem('inspection-photo-receipts',JSON.stringify([...photoReceipts]));return Response.json({attachment,record,acceptedVersion:record.version});
 }
 if(String(input).includes('/team'))return Response.json({identities:[{id:ownerIdentityId,name:'Pilot owner',email:'bobff353@gmail.com'},{id:'fictional-assistant',name:'Fictional assisting inspector',email:'fictional@example.invalid'}],accessRollout:false});
 if(String(input).includes('/email'))return Response.json(String(input).includes('setup')?{configured:true,sender:'Fictional sender (local fixture)',domainStatus:'Local simulation only'}:{deliveries:[]});
 if(String(input).includes('/codes')&&options?.method==='POST'){const b=JSON.parse(String(options.body));try{const entry={...b,data:normalizeCode(b.data),version:b.version+1,updatedAt:new Date().toISOString(),updatedBy:'fictional@example.invalid'};codes=[entry,...codes.filter(c=>c.id!==entry.id)];sessionStorage.setItem('inspection-code-fixture',JSON.stringify(codes));return Response.json({entry,saved:true});}catch(e){return Response.json({error:String(e)},{status:400});}}
 if(options?.method==='POST'){
  if(fail){fail=false;return Response.json({error:'Simulated connection failure. Your draft is kept.'},{status:503});}
  const b=JSON.parse(String(options.body)),current=records.find(r=>r.id===b.id);
  if(b.data?.status==='Completed'&&(b.data.evidenceManifest??[]).some((entry:{id:string;sha256:string})=>photoReceipts.get(entry.id)?.hash!==entry.sha256))return Response.json({error:'Frozen evidence is not confirmed; this signed report remains pending cloud issuance.'},{status:409});
  if((current?.version??0)!==b.version)return Response.json({error:'Stale version'},{status:409});
  try{const data=normalizeInspection(b.data);data.team=reviewTransition(current?.data.team||emptyTeam(),data.team,'bobff353@gmail.com',data.team.reviewerId===ownerIdentityId?'bobff353@gmail.com':'fictional@example.invalid',new Date().toISOString(),Boolean(current&&reviewBasis(current.data)!==reviewBasis(data)));validateInspection(b.kind,data);const record={...b,data,version:b.version+1,updatedAt:new Date().toISOString(),updatedBy:'fictional@example.invalid',createdAt:current?.createdAt||new Date().toISOString()};const followUps:InspectionRecord[]=[];if(data.status==='Completed')for(const[mode,date]of [['routine',data.repeatMonths?data.nextDueDate:''],['reinspection',data.followUpDate]]as const){if(date||(mode==='reinspection'&&data.reinspectionDecision==='Needs scheduling')){const child=followUpRecord(record,mode,date);if(!records.some(r=>r.id===child.id))followUps.push({...child,version:1,createdAt:record.createdAt,updatedAt:record.updatedAt,updatedBy:record.updatedBy});}}records=[record,...followUps,...records.filter(r=>r.id!==b.id)];localStorage.setItem('inspection-fixture',JSON.stringify(records));return Response.json({saved:true,record,followUps});}catch(e){return Response.json({error:String(e)},{status:400});}
 }
 if(String(input).includes('?history='))return Response.json({history:[]});
 return Response.json({records,properties:properties.map(property=>{const profile=profileMap.get(property.id);return profile?{...property,inspectionProfile:profile,occupancyGroup:profile.data.occupancyGroup,additionalOccupancyGroups:profile.data.additionalOccupancyGroups,systems:profile.data.systems}:property;}),attachments,codes,departmentId:'fictional-department',viewerEmail:'bobff353@gmail.com'});
};
createRoot(document.getElementById('root')!).render(<><aside style={{padding:10,background:'#fff0cc',fontFamily:'system-ui'}}>Fictional local inspection test · no department writes <button onClick={()=>{fail=true;}}>Fail next save</button><button onClick={()=>void clearInspectionRecovery().then(()=>location.reload())}>Simulate sign-out cleanup</button><button onClick={()=>{const d=emptyInspection();d.title='test/inspection - report workflow';d.test=true;d.inspector='Fictional inspector';d.actualDate='2026-09-25';d.status='In progress';d.sections=['Custom'];d.checks=[{...freshCheck({id:'fictional-door',label:'Fictional doorway',section:'Custom',source:'Local software fixture'}),result:'Needs attention',location:'Fictional test entrance',observation:'Fictional obstruction for report testing.'}];const r={id:'fictional-ui-inspection',kind:'inspection',data:d,version:1,archived:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),updatedBy:'fictional@example.invalid'};localStorage.setItem('inspection-fixture',JSON.stringify([r]));location.reload();}}>Load report test case</button></aside><main style={{padding:20,fontFamily:'system-ui'}}><Workspace/></main></>);
